 case "place_room":if(!Whole(p["x"])||!Whole(p["y"]))return CommandResult.Fail("Place the room on the grid.");r=new RoomState{id=Id("room"),kind=(string)p["kind"]??"regular",name=(string)p["name"]??"New room",x=(int)p["x"],z=(int)p["y"],width=(int?)p["w"]??4,depth=(int?)p["h"]??3,rotation=(int?)p["rotation"]??0,floor=(int?)p["floor"]??0};if(!RoomShape(r))return CommandResult.Fail("Regular rooms start at 4 × 3; suites at 4 × 5.");r.paid=cost=Price(Interior(h,r)?Fitting(r):Shell(r));h.rooms.Add(r);break;
 case "remove_room":case "move_room":case "copy_room":case "resize_room":r=h.rooms.Find(v=>v.id==id);if(r==null)return CommandResult.Fail("Select an existing room.");var old=JsonConvert.DeserializeObject<RoomState>(JsonConvert.SerializeObject(r));var children=h.objects.Where(v=>v.room==id).ToArray();if(action=="remove_room"){cost=-r.paid;foreach(var c in children){h.objects.Remove(c);State.storage.Add(c);}h.rooms.Remove(r);break;}if(action=="resize_room"){if(!Whole(p["w"])||!Whole(p["h"]))return CommandResult.Fail("Choose whole room dimensions.");r.width=(int)p["w"];r.depth=(int)p["h"];if(!RoomShape(r))return CommandResult.Fail("Keep minimum room dimensions.");double diff=(r.width*r.depth-old.width*old.depth)*25;cost=diff>0?Price(diff):-Math.Min(old.paid,-diff);r.paid+=cost;foreach(var c in children)if(!Rect(r).Encloses(Rect(c))){displaced.Add(Catalog.Find(c.itemId).name);h.objects.Remove(c);State.storage.Add(c);}break;}if(!Whole(p["x"])||!Whole(p["y"]))return CommandResult.Fail("Choose a room position on the grid.");if(action=="copy_room"){r=JsonConvert.DeserializeObject<RoomState>(JsonConvert.SerializeObject(old));r.id=Id("room");r.name="Copy of "+old.name;r.paid=cost=Price(Shell(r));h.rooms.Add(r);}r.x=(int)p["x"];r.z=(int)p["y"];r.rotation=(int?)p["rotation"]??r.rotation;foreach(var child in children){o=action=="copy_room"?JsonConvert.DeserializeObject<ObjectState>(JsonConvert.SerializeObject(child)):child;TransformObject(o,Rect(old),Rect(r),r.rotation-old.rotation);o.room=r.id;if(action=="copy_room"){o.id=Id("object");o.paid=Price(Catalog.Find(o.itemId).price);cost+=o.paid;h.objects.Add(o);}}break;
