 case "place_object":case "move_object":case "retrieve_object":case "store_object":if(action=="place_object"){var item=Catalog.Find((string)p["item"]);if(item==null)return CommandResult.Fail("Choose catalogue furniture.");if(!State.settings.godMode&&item.bond>0&&!State.cats.Any(c=>c.known&&c.bond>=item.bond))return CommandResult.Fail("Reach 20 friendship to unlock this blanket.");cost=Price(item.price);o=new ObjectState{id=Id("object"),itemId=item.id,paid=cost};h.objects.Add(o);}else{o=(action=="retrieve_object"?State.storage:h.objects).Find(v=>v.id==id);if(o==null)return CommandResult.Fail("Select owned furniture.");}if(action=="store_object"){h.objects.Remove(o);o.room="";State.storage.Add(o);}else{if(p["x"]==null||p["y"]==null)return CommandResult.Fail("Choose a furniture position.");o.x=(float)p["x"];o.z=(float)p["y"];o.rotation=(int?)p["rotation"]??0;if(action=="retrieve_object"){State.storage.Remove(o);h.objects.Add(o);}}break;
 case "paint_path":case "erase_path":string style=(string)p["style"]??"earth";if(!new[]{"earth","gravel","brick"}.Contains(style))return CommandResult.Fail("Choose earth, gravel or brick.");if(!(p["cells"] is JArray cells)||cells.Count>10000)return CommandResult.Fail("Draw a path on your lot.");var visited=new HashSet<string>();foreach(var cell in cells){if(!(cell is JArray pair)||pair.Count!=2||!Whole(pair[0])||!Whole(pair[1]))return CommandResult.Fail("Draw paths on whole cells.");int x=(int)pair[0],z=(int)pair[1];string key=x+","+z;if(!visited.Add(key))continue;if(!Owns(new LotRect(x,z,1,1),State.currentHotel))return CommandResult.Fail("Paths must stay on owned land.");h.paths.TryGetValue(key,out var prior);if(action=="erase_path"){cost-=prior?.paid??0;h.paths.Remove(key);}else if(prior?.style!=style){double price=Price(style=="earth"?2:style=="gravel"?4:6);cost+=price-(prior?.paid??0);h.paths[key]=new PathState{style=style,paid=price};}}break;
 case "upgrade":case "upgrade_service":int service=(int?)p["service"]??-1;if(service<0||service>3||h.upgrades[service]>=10)return CommandResult.Fail("This service is fully upgraded.");cost=Math.Round(240*Math.Pow(2,h.upgrades[service]/3.0),MidpointRounding.AwayFromZero);h.upgrades[service]++;h.purchases++;h.level=Math.Min(10,1+h.purchases/2);break;
