 case "draw_room":{int level=(int?)p["floor"]??0;if(!Whole(p["x"])||!Whole(p["y"]))return CommandResult.Fail("Draw the room on the grid.");var drawn=new RoomState{kind=(string)p["kind"]??"regular",x=(int)p["x"],z=(int)p["y"],width=(int?)p["w"]??4,depth=(int?)p["h"]??3,rotation=(int?)p["rotation"]??0,floor=level};if(!IndoorKind(drawn.kind))return CommandResult.Fail("Choose a bedroom, suite or lounge.");if(!RoomShape(drawn))return CommandResult.Fail("Regular rooms start at 4 × 3; suites at 4 × 5.");RoomCells(drawn,out int dx,out int dz,out int dw,out int dd);var floorCells=Floor(h,level,true);var missing=Enumerable.Range(0,dw*dd).Select(i=>(x:dx+i%dw,z:dz+i/dw)).Where(c=>!floorCells.cells.ContainsKey(ShellGrid.Cell(c.x,c.z))).ToList();double grown=0;if(missing.Count>0){var painted=PaintCells(h,level,missing,(bool?)p["buy"]??false);if(!painted.success)return painted;grown=painted.cost;}var placed=Apply("place_room",p);if(!placed.success)return placed;cost=grown+placed.cost;message="Room added";break;}
 case "paint_floor":case "erase_floor":case "set_edge":var shell=ApplyShell(action,p,h);if(!shell.success)return shell;cost=shell.cost;message=shell.message;break;
