 static void TransformObject(ObjectState o,LotRect from,LotRect to,int turns){var a=Rect(o);float x=a.x+a.w/2-from.x-from.w/2,z=a.z+a.d/2-from.z-from.d/2;turns=(turns%4+4)%4;for(int n=0;n<turns;n++){float t=x;x=-z;z=t;}o.rotation=(o.rotation+turns)%4;Size(o,out float w,out float d);o.x=(float)Math.Round((to.x+to.w/2+x-w/2)*2)/2;o.z=(float)Math.Round((to.z+to.d/2+z-d/2)*2)/2;}
 public CommandResult Undo(){return Replay(undo,redo,true);}public CommandResult Redo(){return Replay(redo,undo,false);}CommandResult Replay(List<Edit> from,List<Edit> to,bool reverse){if(from.Count==0)return CommandResult.Fail("Nothing to "+(reverse?"undo.":"redo."));var e=from[from.Count-1];if(!JToken.DeepEquals(BuildSnapshot(State),BuildSnapshot(reverse?e.after:e.before)))return CommandResult.Fail("The building changed since this action.");double cost=reverse?-e.cost:e.cost;if(State.coins<cost)return CommandResult.Fail("Not enough Cat Coins.");var before=Copy(State);var layout=Copy(reverse?e.before:e.after);for(int i=0;i<State.hotels.Count;i++){var h=Hotel(i);var b=layout.hotels[i];h.rooms=b.rooms;h.floors=b.floors;h.objects=b.objects;h.plots=b.plots;h.paths=b.paths;h.upgrades=b.upgrades;h.staff=b.staff;h.level=b.level;h.purchases=b.purchases;h.maid=b.maid;}State.storage=layout.storage;State.coins-=cost;if(!TrySave()){State=before;return CommandResult.Fail("Couldn't save — nothing changed. Tap Retry.");}from.RemoveAt(from.Count-1);to.Add(e);Invalidate();Changed?.Invoke();return CommandResult.Ok(reverse?"Undone":"Redone",cost);}
 static JToken BuildSnapshot(HotelState s){return JToken.FromObject(new{hotels=s.hotels.Select(h=>new{h.rooms,h.floors,h.objects,h.paths,h.plots,h.upgrades,h.staff,h.level,h.purchases,h.maid}).ToArray(),s.storage});} CommandResult Transaction(Action apply,string message){var before=Copy(State);apply();if(!TrySave()){State=before;return CommandResult.Fail("Couldn't save — nothing changed. Tap Retry.");}Changed?.Invoke();return CommandResult.Ok(message);}
 public CommandResult Care(int catId,string tool){tool=(tool??"").ToLowerInvariant();if(tool=="feather")tool="wand";if(!new[]{"pet","brush","wand","yarn","cushion","box"}.Contains(tool))return CommandResult.Fail("Choose a care tool.");var c=State.cats.Find(v=>v.id==catId&&v.known);if(c==null)return CommandResult.Fail("Meet this cat first.");if(c.bond>=100||State.elapsed-c.lastCare<12)return CommandResult.Ok(c.name+" is enjoying your company.");int gain=c.favoriteAction==tool?6:3;var r=Transaction(()=>{c.bond=Math.Min(100,c.bond+gain);c.lastCare=State.elapsed;},c.name+" loved that! +"+gain+" friendship");r.progressChanged=r.success;return r;}
 public CommandResult SetAssistedCare(bool enabled){return Transaction(()=>State.settings.assistedCare=enabled,"Assisted care "+(enabled?"on":"off"));}
 public CommandResult SetSettings(float textScale,bool motion,bool music,bool sound){return SetSettings(textScale,motion,music,sound,State.settings.exterior,State.settings.evening);}public CommandResult SetSettings(float textScale,bool motion,bool music,bool sound,bool exterior,bool evening){if(textScale<1||textScale>1.5||float.IsNaN(textScale))return CommandResult.Fail("Choose a text size from 100% to 150%.");return Transaction(()=>{State.settings.textScale=textScale;State.settings.motion=motion;State.settings.music=music;State.settings.sound=sound;State.settings.exterior=exterior;State.settings.evening=evening;},"Settings saved.");}
 public CommandResult SetGodMode(bool enabled){if(State.settings.godMode==enabled)return CommandResult.Ok("God mode is already "+(enabled?"on":"off"));var r=Transaction(()=>{State.settings.godMode=enabled;if(enabled){for(int i=0;i<4;i++){Hotel(i).owned=true;Hotel(i).plots=Map(i)["plots"].Select(p=>(string)p["id"]).ToList();}foreach(var c in State.cats)c.known=true;State.entitlements=new List<string>{"purrington.cat_club","purrington.forest_lodge","purrington.snowcap_spa"};}},"God mode "+(enabled?"on":"off"));if(r.success){undo.Clear();redo.Clear();Invalidate();ResetLife();}return r;}
 public CommandResult CanTravel(int index){if(index<0||index>3)return CommandResult.Fail("Choose a destination.");if(State.settings.godMode)return CommandResult.Ok("God mode · visit "+(string)Map(index)["name"]);if(Hotel(index).owned)return CommandResult.Ok("Visit "+(string)Map(index)["name"]);if(index==1){const double seasideCost=10000;if(Hotel(0).level<10)return CommandResult.Fail("Reach Meadow level 10 and save 10,000 Cat Coins",seasideCost);return State.coins>=seasideCost?CommandResult.Ok("Open Seaside Suites · 10,000",seasideCost):CommandResult.Fail("Open Seaside Suites · 10,000",seasideCost);}return State.entitlements.Contains(index==2?"purrington.forest_lodge":"purrington.snowcap_spa")?CommandResult.Ok("Visit expansion"):CommandResult.Fail("Unlock this preview expansion first.");}
 public CommandResult Travel(int index){var q=CanTravel(index);if(!q.success)return q;var r=Transaction(()=>{State.coins-=q.cost;Hotel(index).owned=true;State.currentHotel=index;},"Welcome to "+(string)Map(index)["name"]);if(r.success){Invalidate();ResetLife();}return r;}
 public CommandResult GrantEntitlement(string id){int[] ids=id=="purrington.cat_club"?new[]{12,13,14}:id=="purrington.forest_lodge"?new[]{16}:id=="purrington.snowcap_spa"?new[]{15,17}:null;if(ids==null)return CommandResult.Fail("Unknown preview product.");return Transaction(()=>{if(!State.entitlements.Contains(id))State.entitlements.Add(id);foreach(int n in ids)State.cats[n].known=true;},"Preview content unlocked.");}
 public CommandResult Playdate(int cat,int other){if(cat==other||cat<0||other<0||cat>=State.cats.Count||other>=State.cats.Count||!State.cats[cat].known||!State.cats[other].known)return CommandResult.Fail("Choose two known cats.");if(!State.settings.godMode&&(State.cats[cat].bond<10||State.cats[other].bond<10))return CommandResult.Fail("Get to know both cats first · 10 friendship each.");if(!Venues().Any(v=>v.open&&v.role=="seat"&&v.service==2))return CommandResult.Fail("Create a reachable social lounge first.");return Transaction(()=>{State.cats[cat].friend=other;State.cats[other].friend=cat;},"Playdate arranged.");}
 public CommandResult Reconcile(long now){if(now<0)return CommandResult.Fail("Invalid clock.");return Transaction(()=>{if(State.lastSeen>0)State.pendingCoins+=Rate()*Math.Min(28800,Math.Max(0,now-State.lastSeen))/60;State.lastSeen=now;},"Offline earnings ready.");}public CommandResult ClaimOffline(){return Transaction(()=>{State.coins+=State.pendingCoins;State.pendingCoins=0;},"Welcome-back coins collected.");}
 public CommandResult Reset(){var old=State;string error=recoveryError;State=Copy(seed);State.lastSeen=DateTimeOffset.UtcNow.ToUnixTimeSeconds();recoveryError=null;bool saved=false;try{saved=store is IResettableSaveStore reset?reset.Reset(Copy(State)):TrySave();}catch{}if(!saved){State=old;recoveryError=error;return CommandResult.Fail("Could not save reset. Your hotel is unchanged.");}undo.Clear();redo.Clear();Invalidate();ResetLife();Changed?.Invoke();return CommandResult.Ok("A fresh hotel is ready.");}
 public double CatalogPrice(string action,JObject p){if(State.settings.godMode)return 0;if(action=="place_object")return Catalog.Find((string)p["item"])?.price??0;if(action=="place_room")return Shell(new RoomState{kind=(string)p["kind"]??"regular",width=(int?)p["w"]??4,depth=(int?)p["h"]??3});if(action=="place_template"){var t=Content.Templates.FirstOrDefault(v=>(string)v["id"]==(string)p["template"]);return t==null?0:(int)t["w"]*(int)t["h"]*25+t["objects"].Sum(o=>Catalog.Find((string)o["item"]).price);}return 0;} static JObject P(params object[] values){var p=new JObject();for(int i=0;i<values.Length;i+=2)p[(string)values[i]]=JToken.FromObject(values[i+1]);return p;}
 public CommandResult PreviewRoom(int x,int z,int width=4,int depth=3){return Quote("place_room",P("x",x,"y",z,"w",width,"h",depth));}public CommandResult PlaceRoom(int x,int z,int width=4,int depth=3){return Execute("place_room",P("x",x,"y",z,"w",width,"h",depth));}
 public CommandResult PreviewObject(string item,float x,float z,int rotation=0){return Quote("place_object",P("item",item,"x",x,"y",z,"rotation",rotation));}public CommandResult PlaceObject(string item,float x,float z,int rotation=0){return Execute("place_object",P("item",item,"x",x,"y",z,"rotation",rotation));}
 public CommandResult PreviewMoveObject(string id,float x,float z,int rotation=0){return Quote("move_object",P("id",id,"x",x,"y",z,"rotation",rotation));}public CommandResult MoveObject(string id,float x,float z,int rotation=0){return Execute("move_object",P("id",id,"x",x,"y",z,"rotation",rotation));}
 public CommandResult PreviewMoveRoom(string id,int x,int z,int rotation=0){return Quote("move_room",P("id",id,"x",x,"y",z,"rotation",rotation));}public CommandResult MoveRoom(string id,int x,int z,int rotation=0){return Execute("move_room",P("id",id,"x",x,"y",z,"rotation",rotation));}
 public CommandResult PreviewRetrieveObject(string id,float x,float z,int rotation=0){return Quote("retrieve_object",P("id",id,"x",x,"y",z,"rotation",rotation));}public CommandResult RetrieveObject(string id,float x,float z,int rotation=0){return Execute("retrieve_object",P("id",id,"x",x,"y",z,"rotation",rotation));}public CommandResult PlaceStoredObject(string id,float x,float z,int rotation=0){return RetrieveObject(id,x,z,rotation);}public CommandResult RemoveObject(string id){return Execute("store_object",P("id",id));}public CommandResult StoreObject(string id){return RemoveObject(id);}public CommandResult RemoveRoom(string id){return Execute("remove_room",P("id",id));}
 public static bool Valid(HotelState s){try{return ValidCore(s);}catch(Exception e)when(e is ArgumentException||e is InvalidOperationException||e is NullReferenceException||e is OverflowException){return false;}} static bool ValidCore(HotelState s){if(s==null||s.version!=3||!Finite(s.coins)||s.coins<0||!Finite(s.elapsed)||s.elapsed<0||s.nextId<1||s.hotels==null||s.hotels.Count!=4||s.currentHotel<0||s.currentHotel>3||!s.hotels[s.currentHotel].owned||s.cats==null||s.cats.Count!=18||s.storage==null||s.settings==null||s.entitlements==null||!Finite(s.pendingCoins)||s.pendingCoins<0||s.lastSeen<0)return false;var ids=new HashSet<string>();foreach(var h in s.hotels){if(h==null||h.rooms==null||h.floors==null||h.floors.Any(f=>f==null||f.cells==null||f.edges==null)||h.objects==null||h.paths==null||h.plots==null||h.upgrades==null||h.upgrades.Length!=4||h.staff==null||h.staff.Length!=3||h.level<1||h.level>10||h.upgrades.Any(v=>v<0||v>10)||h.staff.Any(v=>v<0||v>3)||h.dirty==null)return false;foreach(var r in h.rooms)if(r==null||string.IsNullOrEmpty(r.id)||!RoomShape(r)||!Finite(r.paid)||r.paid<0||r.paid>Shell(r)||Math.Abs(r.x)>256||Math.Abs(r.z)>256)return false;foreach(var o in h.objects.Concat(s.storage)){if(o==null||string.IsNullOrEmpty(o.id)||Catalog.Find(o.itemId)==null||o.rotation<0||o.rotation>3||!Finite(o.paid)||o.paid<0||o.paid>Catalog.Find(o.itemId).price||!Finite(o.x)||!Finite(o.z)||o.x*2!=Math.Floor(o.x*2)||o.z*2!=Math.Floor(o.z*2))return false;}foreach(var o in h.objects)if(!ids.Add(o.id))return false;}foreach(var o in s.storage)if(!ids.Add(o.id))return false;return s.cats.Select((c,i)=>c!=null&&c.id==i&&c.bond>=0&&c.bond<=100&&Finite(c.lastCare)&&!string.IsNullOrEmpty(c.name)).All(v=>v)&&s.settings.textScale>=1&&s.settings.textScale<=1.5&&ValidateContent(s);}
 static bool Finite(double n){return !double.IsNaN(n)&&!double.IsInfinity(n);}
